mapper.insert:
INSERT INTO room (
    code, sort, type_name, floor_id,
    create_time, create_by, remark
) VALUES (
    #{code}, #{sort}, #{typeName}, #{floorId},
    #{createTime}, #{createBy}, #{remark}
)

mapper.update:
UPDATE room
SET is_deleted = 1
WHERE id = #{id}

mapper.select:
SELECT id, name, bed_count, price, introduction, photo, status, create_time, update_time, create_by, update_by, remark FROM room_type
AND status = #{status}
ORDER BY create_time DESC
